func:
msg.payload = {
    suhu: Math.round((25 + Math.random() * 7) * 10) / 10,
    kelembaban: Math.round((55 + Math.random() * 25) * 10) / 10,
    timestamp: new Date().toISOString()
};
msg.topic = 'iot/sensor';
return msg;

var data = msg.payload;
data.received = new Date().toISOString();

// Batas suhu (default 30, bisa diubah lewat PUT /api/threshold)
var batas = flow.get('threshold');
if (typeof batas !== 'number') batas = 30;
data.batas = batas;
data.alert = data.suhu > batas;

// Simpan data terakhir
flow.set('lastSensor', data);

// Simpan history (maks 50 data)
var history = flow.get('history') || [];
history.push(data);
if (history.length > 50) history.shift();
flow.set('history', history);

// Notifikasi hanya saat berpindah dari normal ke melewati batas
var sebelumnya = flow.get('alertAktif') || false;
flow.set('alertAktif', data.alert);
var notif = null;
if (data.alert && !sebelumnya) {
    notif = {
        topic: 'iot/notifikasi',
        payload: {pesan: 'Suhu melewati batas', suhu: data.suhu, batas: batas, waktu: data.received}
    };
}
return [msg, notif];

// Cek API key dari header X-API-Key
var apiKey = msg.req.headers['x-api-key'];
if (apiKey !== 'iot-2410020106') {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key salah atau tidak ada'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return msg;
}

var data = flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null};
msg.payload = {
    status: 'success',
    data: data,
    server_time: new Date().toISOString()
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

// Cek API key dari header X-API-Key
var apiKey = msg.req.headers['x-api-key'];
if (apiKey !== 'iot-2410020106') {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key salah atau tidak ada'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return msg;
}

var history = flow.get('history') || [];
msg.payload = {
    status: 'success',
    count: history.length,
    data: history
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

// Cek API key dari header X-API-Key
var apiKey = msg.req.headers['x-api-key'];
if (apiKey !== 'iot-2410020106') {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key salah atau tidak ada'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}

var body = msg.payload;

// Body bisa berupa Buffer, teks JSON, atau objek
if (Buffer.isBuffer(body)) body = body.toString();
if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = null; }
}

if (!body || !body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'device dan action wajib diisi'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}

// Kirim perintah ke MQTT (output 2)
var mqttMsg = {payload: body, topic: 'iot/kontrol'};

msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Perintah terkirim', sent: body};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return [msg, mqttMsg];

// Cek API key dari header X-API-Key
var apiKey = msg.req.headers['x-api-key'];
if (apiKey !== 'iot-2410020106') {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key salah atau tidak ada'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return msg;
}

var body = msg.payload;
if (Buffer.isBuffer(body)) body = body.toString();
if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = null; }
}

var batas = (body && body.batas !== undefined && body.batas !== null && body.batas !== '') ? Number(body.batas) : NaN;
if (isNaN(batas) || batas < 0 || batas > 100) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'batas harus berupa angka 0 sampai 100'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return msg;
}

flow.set('threshold', batas);
flow.set('alertAktif', false);

msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Batas suhu diperbarui', batas: batas};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

// Cek API key dari header X-API-Key
var apiKey = msg.req.headers['x-api-key'];
if (apiKey !== 'iot-2410020106') {
    msg.statusCode = 401;
